import { ReactElement } from 'react';

import { StoryFn } from '@storybook/react';

import { Chart } from '../../../../Chart.js';
import { Axis, Legend, Line, ReferenceLine } from '../../../../components/index.js';
import useChartProps from '../../../../hooks/useChartProps.js';
import { workspaceTrendsData } from '../../../../stories/data/data.js';
import { bindWithProps } from '../../../../test-utils/index.js';
import { ChartProps } from '../../../../types/index.js';

export default {
  title: 'React Spectrum Charts 2/Line/Features/Trend Scale',
  component: Line,
};

const defaultChartProps: ChartProps = { data: workspaceTrendsData, minWidth: 400, maxWidth: 800, height: 400 };

const defaultArgs = {
  color: 'series',
  name: 'line0',
  onClick: undefined,
};

const LineStory: StoryFn<typeof Line> = (args): ReactElement => {
  const chartProps = useChartProps(defaultChartProps);
  return (
    <Chart {...chartProps}>
      <Axis position="left" grid title="Users" />
      <Axis position="bottom" labelFormat="time" baseline ticks />
      <Line {...args} />
      <Legend highlight />
    </Chart>
  );
};

const LinearStory: StoryFn<typeof Line> = (args): ReactElement => {
  const chartProps = useChartProps(defaultChartProps);
  return (
    <Chart {...chartProps}>
      <Axis position="left" grid title="Users" />
      <Axis position="bottom" labelFormat="linear" baseline ticks>
        <ReferenceLine value={13} />
      </Axis>
      <Line {...args} />
    </Chart>
  );
};

const TrendScale = bindWithProps(LineStory);
TrendScale.args = {
  ...defaultArgs,
  scaleType: 'point',
};

const LinearTrendScale = bindWithProps(LinearStory);
LinearTrendScale.args = {
  ...defaultArgs,
  dimension: 'point',
  scaleType: 'linear',
};

export { TrendScale, LinearTrendScale };
